import csv
zones = {
 'Perimeter_ZN_2':'1b318110-05c1-54b3-8fea-315f5900b64a',
 'Perimeter_ZN_3':'1689d963-4d6f-57dc-8368-b7b6ce076ca4',
 'Perimeter_ZN_4':'1b3eb9e6-d753-5328-bf35-516ad86dafc4',
}
tot = {z:0.0 for z in zones}
cnt = {z:0 for z in zones}
for row in csv.reader(open(VALUES_CSV)):
    if row[0]=='timeseries_id': continue
    tsid, ts, val = row[0], row[1], float(row[2])
    for z, tid in zones.items():
        if tsid==tid and ts.startswith('2018-10-04'):
            tot[z]+=val; cnt[z]+=1
for z in zones:
    print(z, cnt[z], tot[z], "Wh=", tot[z])
